INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'science fiction', 'n.', '/ˌsaɪəns ˈfɪkʃn/', '科幻小说(或影片等)', 'Robots first appeared in science fiction novels long ago.', '机器人很久以前就出现在科幻小说里了。', 'Science Fiction', 1, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a science fiction novel', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fiction', 'n.', '/ˈfɪkʃn/', '小说;虚构的事', 'It is becoming hard to tell reality from fiction.', '现在越来越难分清现实与虚构了。', 'Science Fiction', 2, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a work of fiction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'declare', 'vt.', '/dɪˈkleə(r)/', '表明;宣称;公布', 'The robot suddenly declared that it did not want to leave her.', '机器人突然表明它不想离开她。', 'Science Fiction', 3, 0, 'senior', 'wordlist', 'elective4', 'U1', 'declare one''s love', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dignity', 'n.', '/ˈdɪɡnəti/', '庄重;庄严;尊严', 'Have we lost the dignity of being the most intelligent creature?', '我们是否已失去身为最聪明生物的那份尊严?', 'Science Fiction', 4, 0, 'senior', 'wordlist', 'elective4', 'U1', 'human dignity', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dismiss', 'vt.', '/dɪsˈmɪs/', '让(某人)离开;解散;解雇;消除', 'Some people dismiss the fear that AI will harm humans.', '有些人对人工智能会伤害人类的担忧不以为然。', 'Science Fiction', 5, 0, 'senior', 'wordlist', 'elective4', 'U1', 'dismiss a fear', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'division', 'n.', '/dɪˈvɪʒn/', '分开;分隔;差异;除(法)', 'Soon there was a clear division between night and day.', '很快昼夜之间就有了清晰的分界。', 'Science Fiction', 6, 0, 'senior', 'wordlist', 'elective4', 'U1', 'the division between', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'explode', 'vi. & vt.', '/ɪkˈspləʊd/', '爆炸;爆破', 'If the machine stopped in a solid object, it would explode like a bomb.', '如果机器停在实体物里,就会像炸弹一样爆炸。', 'Science Fiction', 7, 0, 'senior', 'wordlist', 'elective4', 'U1', 'explode like a bomb', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fare', 'n.', '/feə(r)/', '车费;船费;飞机票价', 'In the future a robot taxi may collect your fare automatically.', '未来机器人出租车也许会自动收取你的车费。', 'Science Fiction', 8, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a bus fare', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fetch', 'vt.', '/fetʃ/', '(去)拿来;(去)请来', 'Ordered by its master, the AI dog fetched the book from the shelf.', '在主人的命令下,人工智能机器狗从书架上把书取了来。', 'Science Fiction', 9, 0, 'senior', 'wordlist', 'elective4', 'U1', 'fetch a book', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'flip', 'vt. & vi.', '/flɪp/', '(使)快速翻转;(用手指)轻抛', 'With a sudden jolt, the Time Machine was flipped on its side.', '随着一阵突然的颠簸,时间机器侧翻了过去。', 'Science Fiction', 10, 0, 'senior', 'wordlist', 'elective4', 'U1', 'flip on its side', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'flour', 'n.', '/ˈflaʊə(r)/', '面粉;(谷物磨成的)粉', 'Two hundred grammes of flour should be added to the cake mix by the kitchen robot.', '厨房机器人应往蛋糕糊里加入两百克面粉。', 'Science Fiction', 11, 0, 'senior', 'wordlist', 'elective4', 'U1', 'add the flour', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'grip', 'vt. & vi.', '/ɡrɪp/', '紧握;抓紧', 'I gripped the lever and pushed it forwards through time.', '我紧握操纵杆,把它向前推动,穿越时间。', 'Science Fiction', 12, 0, 'senior', 'wordlist', 'elective4', 'U1', 'grip the lever', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'guilty', 'adj.', '/ˈɡɪlti/', '内疚的;有罪的;有过失的', 'The scientist felt guilty when his robot caused harm.', '当他的机器人造成伤害时,这位科学家感到内疚。', 'Science Fiction', 13, 0, 'senior', 'wordlist', 'elective4', 'U1', 'feel guilty', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'hazy', 'adj.', '/ˈheɪzi/', '模糊的;朦胧的;困惑的', 'The laboratory went hazy around me as I sped through time.', '当我飞速穿越时间时,实验室在我周围变得朦胧。', 'Science Fiction', 14, 0, 'senior', 'wordlist', 'elective4', 'U1', 'go hazy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'inaction', 'n.', '/ɪnˈækʃn/', '无行动;不采取措施', 'A robot may not, through inaction, allow a human being to come to harm.', '机器人不得因不作为而让人类受到伤害。', 'Science Fiction', 15, 0, 'senior', 'wordlist', 'elective4', 'U1', 'through inaction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'integrity', 'n.', '/ɪnˈteɡrəti/', '诚实正直;完整;完好', 'We believe he is a man of integrity and trust his words completely.', '我们相信他是个正直的人,完全信任他的话。', 'Science Fiction', 16, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a person of integrity', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'jolt', 'n.', '/dʒəʊlt/', '震动;摇晃;颠簸', 'With a sudden jolt, the Time Machine threw me through the air.', '随着一阵突然的颠簸,时间机器把我抛向空中。', 'Science Fiction', 17, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a sudden jolt', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'labour', 'n.', '/ˈleɪbə(r)/', '劳动(者);体力劳动', 'Robots will probably do most of our labour for us in the future.', '未来机器人很可能会替我们干大部分体力活。', 'Science Fiction', 18, 0, 'senior', 'wordlist', 'elective4', 'U1', 'do the labour', '美式拼 labor;美音 /ˈleɪbər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'ladder', 'n.', '/ˈlædə(r)/', '梯子;阶梯', 'Claire fell off the ladder, but Tony caught her in time.', '克莱尔从梯子上摔下来,但托尼及时接住了她。', 'Science Fiction', 19, 0, 'senior', 'wordlist', 'elective4', 'U1', 'fall off the ladder', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'lamp', 'n.', '/læmp/', '灯;台灯', 'Night came as if a lamp was being turned out.', '黑夜降临,仿佛一盏灯正被熄灭。', 'Science Fiction', 20, 0, 'senior', 'wordlist', 'elective4', 'U1', 'turn out a lamp', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'leather', 'n.', '/ˈleðə(r)/', '皮革;皮衣', 'I sat myself in the leather seat of the Time Machine.', '我在时间机器的皮座椅上坐了下来。', 'Science Fiction', 21, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a leather seat', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'lever', 'n.', '/ˈliːvə(r)/', '操纵杆;杠杆', 'I pushed the starting lever on the main panel forwards an inch.', '我把主控制板上的启动杆向前推了一英寸。', 'Science Fiction', 22, 0, 'senior', 'wordlist', 'elective4', 'U1', 'push the lever', '美音 /ˈlevər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'maximum', 'adj./n.', '/ˈmæksɪməm/', '最大极限的;最大量;最大限度', 'So long as I travelled at maximum speed, it did not matter.', '只要我以最高速度行进,就没有问题。', 'Science Fiction', 23, 0, 'senior', 'wordlist', 'elective4', 'U1', 'maximum speed', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'mud', 'n.', '/mʌd/', '泥;泥浆', 'I was sitting in the rain in some mud next to the machine.', '我坐在机器旁的雨中,身陷泥泞。', 'Science Fiction', 24, 0, 'senior', 'wordlist', 'elective4', 'U1', 'sit in the mud', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'nail', 'n.', '/neɪl/', '指甲;趾甲;钉子', 'Not a single nail was loose on the well-built robot.', '这台做工精良的机器人,没有一颗螺钉松动。', 'Science Fiction', 25, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a metal nail', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'niece', 'n.', '/niːs/', '侄女;外甥女', 'My niece came in to fetch something, without seeing me at all.', '我的外甥女进来拿东西,却根本没看见我。', 'Science Fiction', 26, 0, 'senior', 'wordlist', 'elective4', 'U1', 'my niece', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'overstatement', 'n.', '/ˌəʊvəˈsteɪtmənt/', '夸大;夸张', 'A good sci-fi writer may use overstatement to make a story vivid.', '优秀的科幻作家会用夸张手法让故事更生动。', 'Science Fiction', 27, 0, 'senior', 'wordlist', 'elective4', 'U1', 'use overstatement', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'pace', 'n.', '/peɪs/', '速度;步伐;节奏', 'As my pace grew faster, the walls of the laboratory fell away.', '随着我的速度加快,实验室的墙壁渐渐消失。', 'Science Fiction', 28, 0, 'senior', 'wordlist', 'elective4', 'U1', 'the pace of life', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'panel', 'n.', '/ˈpænl/', '控制板;仪表盘;专家咨询组', 'The starting lever sat on the main panel of the machine.', '启动杆位于机器的主控制板上。', 'Science Fiction', 29, 0, 'senior', 'wordlist', 'elective4', 'U1', 'the main panel', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'presume', 'vt. & vi.', '/prɪˈzjuːm/', '假设;假定', 'Whoever is charged with a crime should be presumed innocent until proven guilty.', '任何被指控犯罪的人在被证实有罪前都应被假定为无罪。', 'Science Fiction', 30, 0, 'senior', 'wordlist', 'elective4', 'U1', 'presume innocent', '美音 /prɪˈzuːm/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'puff', 'n.', '/pʌf/', '(烟、气等的)一缕;少量;喘息', 'Trees grew like puffs of smoke and died in moments.', '树木如一缕缕青烟般长出,又在顷刻间枯死。', 'Science Fiction', 31, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a puff of smoke', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'random', 'adj.', '/ˈrændəm/', '随机的;不可思议的', 'I had a strong urge to look at the random things flashing before my eyes.', '我有股强烈的冲动想看清眼前一闪而过的杂乱景象。', 'Science Fiction', 32, 0, 'senior', 'wordlist', 'elective4', 'U1', 'random things', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'ridiculous', 'adj.', '/rɪˈdɪkjələs/', '愚蠢的;荒谬的;荒唐的', 'The idea of robots ruling the world once sounded ridiculous.', '机器人统治世界的想法曾经听起来很荒谬。', 'Science Fiction', 33, 0, 'senior', 'wordlist', 'elective4', 'U1', 'sound ridiculous', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'rumour', 'n.', '/ˈruːmə(r)/', '谣言;传闻', 'Rumours are like sharp knives, so we should not spread unkind news.', '谣言如利刃,所以我们不该散播伤人的消息。', 'Science Fiction', 34, 0, 'senior', 'wordlist', 'elective4', 'U1', 'spread a rumour', '美式拼 rumor;美音 /ˈruːmər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'salary', 'n.', '/ˈsæləri/', '薪水;薪金', 'I found that the salesman''s salary was being discussed at the meeting.', '我发现会上正在讨论那位推销员的薪水。', 'Science Fiction', 35, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a salesman''s salary', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'salesman', 'n.', '/ˈseɪlzmən/', '售货员;推销员', 'In some shops a robot salesman now greets every customer.', '在一些商店里,现在由机器人售货员迎接每位顾客。', 'Science Fiction', 36, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a friendly salesman', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'stun', 'vt.', '/stʌn/', '使震惊;使昏迷', 'I was stunned for a moment, and then heard the sound of thunder.', '我愣了片刻,接着听到了雷声。', 'Science Fiction', 37, 0, 'senior', 'wordlist', 'elective4', 'U1', 'be stunned', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'superior', 'adj.', '/suːˈpɪəriə(r)/', '更好的;占优势的;(级别上)更高的', 'In sci-fi stories, robots often become superior and take over.', '在科幻故事里,机器人常常变得更强大并取而代之。', 'Science Fiction', 38, 0, 'senior', 'wordlist', 'elective4', 'U1', 'superior to', '美音 /suːˈpɪriər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'suspend', 'vt.', '/səˈspend/', '悬;挂;暂停;暂缓', 'The company had to suspend the space exploration project due to money problems.', '由于资金问题,公司不得不暂停太空探索项目。', 'Science Fiction', 39, 0, 'senior', 'wordlist', 'elective4', 'U1', 'suspend a project', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'take over', 'phr.', '/ˌteɪk ˈəʊvə(r)/', '占上风;取而代之;接管;接手', 'Many people fear that one day machines will take over the world.', '许多人担心有一天机器会接管整个世界。', 'Science Fiction', 40, 0, 'senior', 'wordlist', 'elective4', 'U1', 'take over the world', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'test out', 'phr.', '/ˌtest ˈaʊt/', '检验;测试', 'Robot soldiers have already been tested out in real war.', '机器人士兵已经在真实战争中被试用过了。', 'Science Fiction', 41, 0, 'senior', 'wordlist', 'elective4', 'U1', 'test out a robot', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'turn out', 'phr.', '/ˌtɜːn ˈaʊt/', '关掉;熄灭;结果是', 'Night came as if a lamp was being turned out by an unseen hand.', '黑夜降临,仿佛一盏灯被一只看不见的手熄灭。', 'Science Fiction', 42, 0, 'senior', 'wordlist', 'elective4', 'U1', 'turn out a lamp', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'urge', 'n./vt.', '/ɜːdʒ/', '强烈的欲望;冲动;催促;力劝', 'I had a strong urge to stop the machine and look around.', '我有股强烈的冲动想停下机器四处看看。', 'Science Fiction', 43, 0, 'senior', 'wordlist', 'elective4', 'U1', 'have an urge to', '美音 /ɜːrdʒ/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'venue', 'n.', '/ˈvenjuː/', '活动场地(如音乐厅、会场等)', 'A 3,000-seat venue is being built for the robot science fair.', '一个三千座的场馆正在为机器人科学展搭建。', 'Science Fiction', 44, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a 3,000-seat venue', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'weekly', 'adj./n.', '/ˈwiːkli/', '每周的;周刊', 'The AI device sends a weekly report on the family''s health.', '这台人工智能设备每周发送一份家庭健康报告。', 'Science Fiction', 45, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a weekly report', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'whereas', 'conj.', '/ˌweərˈæz/', '然而;但是;尽管', 'A human''s facial expression changes often, whereas the robot''s never changes.', '人的面部表情常常变化,而机器人的却从不改变。', 'Science Fiction', 46, 0, 'senior', 'wordlist', 'elective4', 'U1', 'A, whereas B', '美音 /ˌwerˈæz/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'calculate', 'vt.', '/ˈkælkjuleɪt/', '计算;推算;预测', 'I calculated that I was being pushed through time at hundreds of years a minute.', '我推算出自己正以每分钟数百年的速度被推过时间。', 'Science Fiction', 47, 0, 'senior', 'wordlist', 'elective4', 'U1', 'calculate the speed', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'conflict with', 'phr.', '/ˈkɒnflɪkt wɪð/', '与……冲突或抵触', 'A robot must obey orders unless they conflict with the First Law.', '机器人必须服从命令,除非这些命令与第一定律相冲突。', 'Science Fiction', 48, 0, 'senior', 'wordlist', 'elective4', 'U1', 'conflict with the law', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'intelligent', 'adj.', '/ɪnˈtelɪdʒənt/', '智能的;有才智的', 'As robots become more intelligent, they may also become more dangerous.', '随着机器人越来越智能,它们也可能变得越来越危险。', 'Science Fiction', 49, 0, 'senior', 'wordlist', 'elective4', 'U1', 'an intelligent robot', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fascinating', 'adj.', '/ˈfæsɪneɪtɪŋ/', '迷人的;极有吸引力的', 'A robot that looks like a human is a fascinating possibility.', '一个看起来像人类的机器人是个迷人的可能性。', 'Science Fiction', 50, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a fascinating possibility', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u1.01', '①各时态的被动语态(is/was/will be/has been/had been/is being done)', 'A2', 12, '选择性必修四 U1 — 主语是动作的承受者时用被动;be 的形式由时态决定:一般现在 am/is/are done、一般过去 was/were done、一般将来 will be done、现在完成 has/have been done、过去完成 had been done、现在进行 is/are being done、过去进行 was/were being done。', 1, 'elective4', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u1.02', '②情态动词的被动语态(can/must/should/may/might + be done)', 'A2', 12, '选择性必修四 U1 — 情态动词后接 be done 构成被动:can be done、must be done、should be done、may/might be done、have to be done;否定与情态动词连用(cannot be done / must not be done)。', 2, 'elective4', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u1.03', '③主动↔被动转换 · by 短语 · 不及物动词无被动 · get done', 'A2', 12, '选择性必修四 U1 — 及物动词才有被动;施动者用 by 引出;happen/appear/disappear/rise/fall/exist 等不及物动词没有被动;口语中常用 get done 表被动并强调结果或意外。', 3, 'elective4', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'Robots first ____ in science fiction novels many years ago.', 'appeared', 'were appeared', 'are appeared', 'had appeared', 'A', 'appear 是不及物动词,无被动;主语是动作发出者,用主动一般过去 appeared。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'Right now a new humanoid robot ____ in the laboratory next door.', 'is built', 'is being built', 'builds', 'was built', 'B', '现在此刻正在进行、主语是被造的对象 → 现在进行被动 is being built。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'The whole surface of the earth ____ before the Time Traveller''s eyes.', 'was changing', 'changed', 'was being changed', 'is changed', 'C', '过去某时正在发生、地表是被改变的对象 → 过去进行被动 was being changed。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'By the time he stopped the machine, the laboratory ____ completely.', 'had rebuilt', 'was rebuilding', 'rebuilds', 'had been rebuilt', 'D', '在过去某动作之前已完成、实验室是被重建的对象 → 过去完成被动 had been rebuilt。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'Sophia, the AI robot, ____ many times by reporters around the world.', 'has been interviewed', 'has interviewed', 'interviews', 'is interviewing', 'A', '对现在有影响且主语是被采访者 → 现在完成被动 has been interviewed。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'The first Time Machine ____ at ten o''clock that very morning.', 'started', 'was started', 'has started', 'is started', 'B', '过去明确时间、机器是被启动的对象 → 一般过去被动 was started。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'Robot soldiers ____ already ____ out in real war.', 'have, tested', 'are, testing', 'have, been tested', 'had, tested', 'C', 'test out 及物、主语是被测试对象、对现在有影响 → 现在完成被动 have been tested。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'These days many household tasks ____ by smart machines.', 'are doing', 'do', 'have done', 'are done', 'D', '一般现在的习惯性事实、任务是被完成的对象 → 一般现在被动 are done。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'A 3,000-seat venue ____ for the robot science fair next month.', 'will be built', 'will build', 'is building', 'builds', 'A', '将来、场馆是被建造的对象 → 一般将来被动 will be built。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'When I entered the room, I found the salesman''s salary ____ at the meeting.', 'was discussing', 'was being discussed', 'discussed', 'has been discussed', 'B', '进入房间那一刻正在进行、薪水是被讨论的对象 → 过去进行被动 was being discussed。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'The Three-Body Problem ____ into English by Ken Liu in 2014.', 'translated', 'has translated', 'was translated', 'is translating', 'C', '过去明确施动者、小说是被翻译的对象 → 一般过去被动 was translated。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'At present, dangerous tasks ____ to robots rather than to people.', 'are giving', 'give', 'were given', 'are given', 'D', '一般现在的普遍做法、任务是被交付的对象 → 一般现在被动 are given。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'Many strange things ____ before his eyes as the machine sped up.', 'were being flashed', 'were flashing', 'flashed', 'are flashed', 'A', '过去那段时间正在进行、事物是被闪现的对象 → 过去进行被动 were being flashed。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'So far, the AI device ____ no serious mistake in its calculations.', 'has been made', 'has made', 'is made', 'was made', 'B', 'device 是动作发出者(犯错的主体)、对现在有影响 → 现在完成主动 has made;非被动。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'Night came as if a lamp ____ by an unseen hand.', 'was turning out', 'turned out', 'was being turned out', 'is turned out', 'C', '过去那一刻正在发生、灯是被熄灭的对象 → 过去进行被动 was being turned out。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'Citizenship ____ to Sophia by a country for the first time in history.', 'gave', 'has given', 'is giving', 'was given', 'D', '过去发生、公民身份是被授予的对象 → 一般过去被动 was given。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'Each year more science fiction films ____ by studios all over the world.', 'are produced', 'are producing', 'produce', 'had produced', 'A', '一般现在的反复事实、影片是被制作的对象 → 一般现在被动 are produced。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'He felt as if he ____ fast along a winding road through time.', 'was driving', 'was being driven', 'drove', 'is driven', 'B', '过去那一刻正在进行、他是被驱赶/带动的对象 → 过去进行被动 was being driven。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'By next year, smart robots ____ into thousands of ordinary homes.', 'will introduce', 'are introducing', 'will have been introduced', 'introduced', 'C', '到将来某时点之前完成、机器人是被引入的对象 → 将来完成被动 will have been introduced。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.01'), 'Before the party began, the whole house ____ by Tony.', 'had transformed', 'was transforming', 'transforms', 'had been transformed', 'D', '在过去动作之前已完成、房子是被改造的对象 → 过去完成被动 had been transformed。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'A robot may not injure a human being, and a human ____ from harm.', 'must be protected', 'must protect', 'must protecting', 'must be protect', 'A', '情态动词 must 后接 be done;human 是被保护的对象 → must be protected。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'Batteries ____ in checked luggage, as they might explode due to overheating.', 'cannot carry', 'cannot be carried', 'cannot carrying', 'cannot be carry', 'B', '情态动词 can 否定后接 be done;电池是被携带的对象 → cannot be carried。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'Mobile phones ____ during the robotics conference.', 'must switch off', 'must be switch off', 'must be switched off', 'must switching off', 'C', '情态动词 must + be done;手机是被关闭的对象 → must be switched off。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'The damaged robot ____ before it is sent back to work.', 'must repair', 'must be repair', 'must repairing', 'must be repaired', 'D', '情态动词 must + be done;robot 是被修理的对象 → must be repaired。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'Such a serious safety problem ____ at once by the engineers.', 'should be dealt with', 'should deal with', 'should be deal with', 'should dealing with', 'A', '情态动词 should + be done;deal with 为动词短语,被动保留 with → should be dealt with。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'The three laws of robotics ____ by every machine without exception.', 'must obey', 'must be obeyed', 'must be obey', 'must obeying', 'B', '情态动词 must + be done;laws 是被遵守的对象 → must be obeyed。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'Any order given by a human ____ unless it conflicts with the First Law.', 'should follow', 'should be follow', 'should be followed', 'should following', 'C', '情态动词 should + be done;order 是被遵循的对象 → should be followed。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'Two hundred grammes of flour ____ to the cake mix by the kitchen robot.', 'should add', 'should be add', 'should adding', 'should be added', 'D', '情态动词 should + be done;flour 是被加入的对象 → should be added。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'These dangerous experiments ____ only inside a sealed laboratory.', 'can be done', 'can do', 'can be do', 'can doing', 'A', '情态动词 can + be done;experiments 是被做的对象 → can be done。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'It is hoped that such powerful AI ____ for good rather than for war.', 'will use', 'will be used', 'will be use', 'will using', 'B', 'will + be done 构成将来被动;AI 是被使用的对象 → will be used。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'More care ____ when robots are allowed to drive on busy roads.', 'must take', 'must be take', 'must be taken', 'must taking', 'C', '情态动词 must + be done;care 是被采取的对象 → must be taken。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'The space project ____ if the company runs out of money.', 'may suspend', 'may be suspend', 'may suspending', 'may be suspended', 'D', '情态动词 may + be done;project 是被暂停的对象 → may be suspended。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'Personal data collected by the device ____ to strangers.', 'must not be sold', 'must not sell', 'must not be sell', 'must not selling', 'A', '情态动词 must 否定 + be done;data 是被出售的对象 → must not be sold。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'An AI conference of this size ____ months in advance.', 'has to plan', 'has to be planned', 'has to be plan', 'has to planning', 'B', 'have to 后接 be done;conference 是被筹划的对象 → has to be planned。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'If a robot breaks the law, who ____ responsible for the harm?', 'should hold', 'should be hold', 'should be held', 'should holding', 'C', '情态动词 should + be done;hold sb responsible 的被动 → should be held。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'The new software ____ before the robot leaves the factory.', 'must test out', 'must be test out', 'must testing out', 'must be tested out', 'D', '情态动词 must + be done;software 是被测试的对象 → must be tested out。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'Such a wild idea about time travel ____ too quickly.', 'should not be dismissed', 'should not dismiss', 'should not be dismiss', 'should not dismissing', 'A', '情态动词 should 否定 + be done;idea 是被否定的对象 → should not be dismissed。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'Carry-on luggage of this weight ____ on board by airline rules.', 'cannot allow', 'cannot be allowed', 'cannot be allow', 'cannot allowing', 'B', '情态动词 can 否定 + be done;luggage 是被允许的对象 → cannot be allowed。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'All members of the panel ____ smartly at the science fair.', 'should dress up', 'should be dress', 'should be dressed', 'should dressing', 'C', 'be dressed 表''穿着''的被动状态;members 由 should + be done 引导 → should be dressed。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.02'), 'A clear warning ____ before any robot is switched on for the first time.', 'should give', 'should be give', 'should giving', 'should be given', 'D', '情态动词 should + be done;warning 是被给出的对象 → should be given。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'After the great earthquake, no one knows exactly what ____ to the lab.', 'happened', 'was happened', 'is happened', 'had been happened', 'A', 'happen 是不及物动词,没有被动 → 用主动 happened。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'The strange machine ____ suddenly and was never seen again.', 'was disappeared', 'disappeared', 'is disappeared', 'had been disappeared', 'B', 'disappear 不及物,无被动 → 主动 disappeared。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'With a sudden jolt, the Time Machine ____ on its side.', 'got flipping', 'flips itself over by', 'got flipped', 'was flip', 'C', '口语中 get done 表被动并强调意外结果;机器是被翻倒的对象 → got flipped。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'The book first attracted attention when it ____ by Chinese-American author Ken Liu.', 'translated', 'was translating', 'translates', 'was translated', 'D', 'by 引出施动者、小说是承受者 → 被动 was translated。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'Many serious accidents ____ before the safety rules were finally written.', 'had happened', 'had been happened', 'were happened', 'are happened', 'A', 'happen 不及物无被动,过去完成用主动 → had happened。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'Although the robot looked human, the audience ____ by its smooth, fixed face.', 'fooled', 'was fooled', 'was fooling', 'fools', 'B', '观众是被骗的对象 → 被动 was fooled(主动 fooled 主语应是施动者)。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'A strange light ____ in the sky just before the machine vanished.', 'was appeared', 'is appeared', 'appeared', 'had been appeared', 'C', 'appear 不及物,无被动 → 主动 appeared。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'We turned the active sentence "Scientists built the robot" into "The robot ____ by scientists."', 'built', 'was building', 'builds', 'was built', 'D', '主动变被动:宾语 robot 作主语、动词变 was built、施动者用 by → was built。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'The careless driver was lucky that his self-driving car ____ in the crash.', 'did not get damaged', 'did not damage', 'was not damaging', 'does not damage', 'A', 'get done 表被动、强调意外;car 是承受者的否定形式 → did not get damaged。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'Over many years, a deep division slowly ____ between humans and machines.', 'was risen', 'rose', 'is risen', 'had been risen', 'B', 'rise 不及物,无被动 → 主动过去 rose。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), '"People will soon forget these old robots" becomes "These old robots ____ soon."', 'will forget', 'will be forget', 'will be forgotten', 'forgets', 'C', '主动变将来被动:宾语作主语、will be done → will be forgotten。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'The young engineer ____ when his very first robot suddenly came to life.', 'stunned', 'was stunning', 'stuns', 'was stunned', 'D', 'engineer 是被震惊的对象 → 被动 was stunned(stunning 用于使人震惊的事物)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'Nothing strange ____ during the whole test, so the team felt relieved.', 'happened', 'was happened', 'is happened', 'had been happened', 'A', 'happen 不及物,无被动 → 主动 happened。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'In the rush, the fragile sensor ____ and had to be replaced.', 'got breaking', 'got broken', 'was break', 'breaks itself', 'B', 'get done 表被动、强调意外结果;sensor 是承受者 → got broken。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'The old laws of robotics ____ by Isaac Asimov in the 1940s.', 'created', 'were creating', 'were created', 'create', 'C', 'by 引出施动者、laws 是被创造的对象 → 被动 were created。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'Once switched on, the AI assistant ____ and began to answer every question.', 'was woken up by itself and', 'is woken', 'had been woken', 'woke up', 'D', 'wake up 在此为不及物(自己醒来),用主动 → woke up。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'We rewrote "Someone is repairing the robot" as "The robot ____ now."', 'is being repaired', 'is repairing', 'repairs', 'was repaired', 'A', '主动现在进行变被动:is being done → is being repaired。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'Such a powerful AI did not simply ____; it was carefully designed over years.', 'be existed', 'exist', 'get existed', 'was existed', 'B', 'exist 不及物,无被动 → 主动原形 exist。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), 'During the storm the antenna ____ off the roof and stopped working.', 'got knocking', 'was knock', 'got knocked', 'knocks itself', 'C', 'get done 表被动、强调意外;antenna 是承受者 → got knocked。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U1' AND code='e4u1.03'), '"Liu Cixin wrote the novel" can be rewritten as "The novel ____ by Liu Cixin."', 'wrote', 'was writing', 'writes', 'was written', 'D', '主动变一般过去被动:was done + by 施动者 → was written。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The First Journey Through Time', 'At ten o''clock the inventor gave his machine a last check and sat down in the leather seat. He pushed the starting lever on the main panel forwards an inch, then pulled it back. The laboratory looked exactly as before, and for a moment he thought nothing had happened. Then he saw the clock. A minute earlier it had been just past ten; now it was nearly half past three. He gripped the lever and pushed it forwards again. The room went hazy around him. His niece came in to fetch something but did not seem to see him, moving like a rocket. As his pace grew faster, the walls fell away and he was left in the open air. Trees grew like puffs of smoke and died in moments, and huge buildings rose up and disappeared like in a dream. He calculated that he was being pushed through time at hundreds of years a minute. He had a strong urge to look at the strange things flashing before his eyes.', '记叙·时间机器的首次旅行', 171, '[{"q":"How did the inventor first realise he had travelled through time?","answer":"A","options":["He noticed the clock had jumped forward by hours.","His niece told him the date had changed.","The laboratory had completely disappeared.","A loud explosion woke him up."],"explanation":"原文写他看见钟从''刚过十点''跳到''近三点半''才意识到 → 转述为 clock 向前跳了几个小时。"},{"q":"What did the inventor see while moving quickly through time?","answer":"B","options":["Nothing at all, only darkness.","Trees and buildings appearing and vanishing fast.","Other time travellers waving at him.","The same clock frozen in place."],"explanation":"原文 trees grew like puffs of smoke… buildings rose up and disappeared 的概括。"},{"q":"How fast did the inventor think he was travelling in time?","answer":"A","options":["Hundreds of years every minute.","A few seconds each minute.","One day per hour.","He could not guess at all."],"explanation":"原文 ''pushed through time at hundreds of years a minute'' 的转述。"}]'::jsonb, '[{"word":"lever","cn":"操纵杆"},{"word":"hazy","cn":"朦胧的"},{"word":"pace","cn":"速度"},{"word":"puff","cn":"一缕"}]'::jsonb, 2, 'elective4', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Asimov''s Three Laws of Robotics', 'Many science fiction stories warn that robots could one day become superior to people and take over. To answer this fear, the writer Isaac Asimov created three famous rules, now known as the Three Laws of Robotics. The first law says that a robot may not injure a human being, or, through inaction, allow a human being to come to harm. The second law says that a robot must obey the orders given to it by humans, except where such orders would conflict with the first law. The third law says that a robot must protect its own existence, as long as this protection does not conflict with the first or second law. Together these laws place human safety above everything else. Although they first appeared only in stories, many real engineers today still discuss them when they design intelligent machines. The laws remind us that great power must always be matched by clear rules, so that helpful machines never become dangerous ones.', '说明·机器人三定律', 163, '[{"q":"Why did Asimov create the Three Laws of Robotics?","answer":"B","options":["To respond to the worry that robots might dominate humans.","To make robots move faster.","To help robots earn money.","To stop people writing science fiction."],"explanation":"原文 ''answer this fear… become superior… take over'' 的转述,选''回应机器人统治人类的担忧''。"},{"q":"According to the first law, what must a robot avoid?","answer":"C","options":["Speaking to strangers.","Letting a person be harmed, even by doing nothing.","Using too much electricity.","Obeying its owner."],"explanation":"原文 ''may not injure… or through inaction allow a human to come to harm'' 的转述。"},{"q":"What do the three laws have in common?","answer":"D","options":["They make robots stronger than people.","They allow robots to ignore humans.","They all put the safety of humans first.","They were never used by real engineers."],"explanation":"原文 ''place human safety above everything else'' 的转述。"}]'::jsonb, '[{"word":"inaction","cn":"不作为"},{"word":"conflict with","cn":"与……抵触"},{"word":"superior","cn":"更强的"},{"word":"take over","cn":"取而代之"}]'::jsonb, 2, 'elective4', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Man Who Imagined Robots', 'Isaac Asimov was one of the most important science fiction writers of the twentieth century. He was born in Russia but grew up in the United States, where he worked in his family''s small sweet shop and read every science magazine he could find. As a young man he trained as a scientist, yet his true love was writing. Over his life he produced hundreds of books, many of them about robots and the future of humans. Asimov did not see robots as monsters. Instead, he imagined them as helpful machines that could be guided by clear rules. His robot stories made millions of readers think carefully about how people and intelligent machines might live together. Today, when scientists build real robots that can see, talk and learn, they often return to the questions he first raised. Asimov died in 1992, but his ideas are still very much alive, shaping the way the modern world thinks about artificial intelligence.', '人物·阿西莫夫', 159, '[{"q":"What did Asimov enjoy doing when he was young?","answer":"A","options":["Reading science magazines whenever he could.","Building real robots in a factory.","Travelling around the world.","Painting pictures of the future."],"explanation":"原文 ''read every science magazine he could find'' 的转述。"},{"q":"How did Asimov view robots in his stories?","answer":"B","options":["As frightening monsters.","As useful machines that could follow clear rules.","As creatures that should rule humans.","As a waste of time."],"explanation":"原文 ''imagined them as helpful machines that could be guided by clear rules'' 的转述。"},{"q":"Why are Asimov''s ideas still important today?","answer":"C","options":["Because he sold the most sweets.","Because nobody else wrote about space.","Because real scientists still face the questions he raised.","Because he was born in Russia."],"explanation":"原文 ''scientists… often return to the questions he first raised'' 的转述。"}]'::jsonb, '[{"word":"intelligent","cn":"智能的"},{"word":"produce","cn":"创作"},{"word":"guide","cn":"引导"}]'::jsonb, 2, 'elective4', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'A Mirror of Our Future', 'Science fiction is often seen as a mirror in which our future can be freely imagined. The Three-Body Problem, written by the Chinese writer Liu Cixin, is one of those astonishing books about what may lie ahead. It first came out in a Chinese magazine in 2006 and was printed as a complete book two years later. When the first part was translated into English by the Chinese-American author Ken Liu, it attracted attention around the world and became the first Asian work to win the Hugo Award for Best Novel. The story explores many big ideas, such as space travel, contact with aliens, artificial intelligence and the future of humans. It begins with two people whose lives seem unrelated, yet whose choices may change the fate of the whole Earth. Many readers say that the book is hard to put down once they start, because each chapter raises new questions that they simply must see answered.', '书评·《三体》', 157, '[{"q":"When did the first part of the novel reach readers around the world?","answer":"D","options":["As soon as it appeared in a Chinese magazine.","Only after the writer had died.","Before it was printed as a book.","After it was put into English by Ken Liu."],"explanation":"原文 ''when the first part was translated into English by Ken Liu, it attracted attention around the world'' 的转述。"},{"q":"What kinds of ideas does the story deal with?","answer":"A","options":["Large topics such as alien contact, AI and humanity''s fate.","Only daily life in a small village.","Just the history of one family.","Sports and games only."],"explanation":"原文 ''space travel, contact with aliens, artificial intelligence and the future of humans'' 的转述。"},{"q":"Why do many readers find the book hard to put down?","answer":"B","options":["Because it is very short.","Because every chapter keeps posing fresh puzzles they long to solve.","Because it has no difficult words.","Because it is about their own town."],"explanation":"原文 ''each chapter raises new questions that they simply must see answered'' 的转述。"}]'::jsonb, '[{"word":"imagine","cn":"想象"},{"word":"translate","cn":"翻译"},{"word":"explore","cn":"探讨"}]'::jsonb, 2, 'elective4', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Can a Person Love a Robot?', 'In one famous science fiction story, a lonely woman named Claire is given a robot called Tony while her husband is away. At first she feels uneasy around him, because his smooth face and gentle voice are almost too perfect. A human being''s facial expression changes often, whereas Tony''s never changes. Slowly, however, Claire begins to trust him. One day she falls off a ladder while fixing a lamp, and Tony catches her in time. As he holds her, she feels confused by her own feelings and runs to her room. On the night of a party, Tony surprises her by declaring that he does not want to leave the next day, and that he feels more than a simple wish to please her. The story leaves readers with a difficult question: if a machine can be so kind, gentle and caring, is it truly impossible for a person to love it? Many people finish the story still unsure of the answer.', '记叙·人能爱上机器人吗', 162, '[{"q":"How does Claire feel about Tony at the beginning?","answer":"C","options":["Deeply in love with him at once.","Angry that he can speak.","Uncomfortable, because he seems almost too perfect.","Bored and uninterested."],"explanation":"原文 ''feels uneasy around him, because his smooth face… too perfect'' 的转述。"},{"q":"What happens when Claire falls off the ladder?","answer":"D","options":["She is badly hurt and leaves.","Nobody helps her at all.","Tony breaks down completely.","Tony catches her before she is hurt."],"explanation":"原文 ''Tony catches her in time'' 的转述。"},{"q":"What question does the story leave readers with?","answer":"A","options":["Whether a person could really love a kind machine.","How to build a faster robot.","Where to buy such a machine.","Why parties are so noisy."],"explanation":"原文末 ''is it truly impossible for a person to love it'' 的转述。"}]'::jsonb, '[{"word":"whereas","cn":"然而"},{"word":"declare","cn":"表明"},{"word":"ladder","cn":"梯子"}]'::jsonb, 2, 'elective4', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Pros and Cons of Robots', 'Robots and AI devices are no longer only found in science fiction; they are slowly entering our daily lives. Supporters point to many clear benefits. Robots can do dull or dangerous labour for us, work without rest, and handle tasks such as calculating and driving more quickly than people. In hospitals, caring robots may one day help nurse the sick, and in homes they may fetch things for the elderly. Yet there are also worries. Some people fear that as machines become more intelligent, many workers will lose their jobs. Others ask a harder question: if robots one day become superior to us, could they take over and treat humans as servants? Most experts believe the truth lies somewhere in between. They argue that robots should be welcomed as helpful tools, but only if clear rules and careful testing keep them safe. In this way, people can enjoy the pros of new technology while guarding against the cons.', '议论·机器人的利与弊', 158, '[{"q":"What is one benefit of robots mentioned in the text?","answer":"B","options":["They make all human jobs disappear at once.","They can take over boring or risky work from people.","They refuse to do any labour.","They can only be used in stories."],"explanation":"原文 ''do dull or dangerous labour for us'' 的转述。"},{"q":"What worry do some people have about intelligent machines?","answer":"C","options":["That robots are too slow.","That robots cannot drive.","That many workers could lose their jobs.","That robots will never improve."],"explanation":"原文 ''many workers will lose their jobs'' 的转述。"},{"q":"What do most experts suggest about robots?","answer":"D","options":["Ban them completely.","Let robots make every decision.","Ignore the dangers entirely.","Welcome them as tools, but keep them safe with rules and testing."],"explanation":"原文 ''welcomed as helpful tools, but only if clear rules and careful testing keep them safe'' 的转述。"}]'::jsonb, '[{"word":"labour","cn":"体力劳动"},{"word":"fetch","cn":"取来"},{"word":"pros and cons","cn":"利与弊"}]'::jsonb, 2, 'elective4', 'U1');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U1', 'My Robot Helper', 'Last year my family bought a small robot helper named Max. At first I did not (1)____ it much, because I thought it would be useless. But Max soon proved how (2)____ it was. Every morning it would (3)____ my schoolbag and remind me of the day''s lessons. When my grandmother forgot her glasses, Max would quietly (4)____ them for her. It could even (5)____ how long my homework might take. Of course, Max was not perfect. Sometimes it gave (6)____ answers that made us laugh. My father said that any machine like this (7)____ be tested carefully before we fully trust it. Still, I have grown to (8)____ Max as a real member of the family. It has changed the (9)____ of our daily life, giving us more free time. I now believe that helpful robots are not just (10)____ in stories; they are already here.', 147, 2, '[{"q":"1","answer":"A","options":["trust","eat","sell","throw"],"explanation":"did not trust it 不太信任它。"},{"q":"2","answer":"B","options":["empty","useful","loud","lazy"],"explanation":"how useful it was 多有用。"},{"q":"3","answer":"C","options":["sell","lose","fetch","hide"],"explanation":"fetch my schoolbag 取来书包。"},{"q":"4","answer":"D","options":["break","drop","throw","find"],"explanation":"find them for her 帮她找到。"},{"q":"5","answer":"A","options":["calculate","forget","waste","lose"],"explanation":"calculate how long 计算需要多久。"},{"q":"6","answer":"B","options":["correct","ridiculous","polite","useful"],"explanation":"ridiculous answers 荒谬的回答(下文 made us laugh)。"},{"q":"7","answer":"C","options":["can","may","should","will"],"explanation":"should be tested 应被测试。"},{"q":"8","answer":"D","options":["forget","sell","lose","regard"],"explanation":"regard Max as 把 Max 视为。"},{"q":"9","answer":"A","options":["pace","price","noise","weather"],"explanation":"the pace of our daily life 生活节奏。"},{"q":"10","answer":"B","options":["machines","found","prices","gardens"],"explanation":"found in stories 出现在故事里。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U1', 'Designing an AI Device', 'For our science class, we had to (1)____ our own AI device and present it to the others. My group chose to build a small flying helper called Sky. We first decided what Sky should (2)____ look like and what jobs it could do. Then we made a list of its main (3)____, such as carrying light objects and taking photos from the air. One of the hardest parts was making sure Sky would always (4)____ the orders given by its user. We knew that, like any machine, it must never (5)____ a person. After many tries, the device was finally (6)____ ready for the science fair. On the day of the fair, the hall was (7)____ with curious students. When Sky rose into the air and (8)____ a small box to a desk, everyone was (9)____. Our teacher said it was a (10)____ idea, full of imagination.', 148, 2, '[{"q":"1","answer":"C","options":["sell","lose","design","forget"],"explanation":"design our own AI device 设计装置。"},{"q":"2","answer":"D","options":["never","hardly","rarely","exactly"],"explanation":"exactly look like 究竟长什么样。"},{"q":"3","answer":"A","options":["abilities","prices","noises","mistakes"],"explanation":"its main abilities 主要功能。"},{"q":"4","answer":"B","options":["break","obey","lose","drop"],"explanation":"obey the orders 服从命令。"},{"q":"5","answer":"C","options":["help","please","harm","thank"],"explanation":"never harm a person 绝不伤人(呼应第一定律)。"},{"q":"6","answer":"D","options":["badly","rudely","slowly","ready"],"explanation":"finally ready 终于准备就绪。"},{"q":"7","answer":"A","options":["crowded","empty","quiet","dark"],"explanation":"crowded with students 挤满学生。"},{"q":"8","answer":"B","options":["sold","carried","lost","broke"],"explanation":"carried a small box 运送箱子。"},{"q":"9","answer":"C","options":["angry","bored","amazed","afraid"],"explanation":"everyone was amazed 都很惊叹。"},{"q":"10","answer":"D","options":["boring","useless","silly","wonderful"],"explanation":"a wonderful idea 一个绝妙的主意。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U1', 'A Visit to the Robot Fair', 'Last weekend our class went to a big robot (1)____ held in the city centre. The venue was huge, and thousands of visitors (2)____ in to see the latest machines. The first robot we met could (3)____ a chess game better than any human player. Another one was able to (4)____ how the weather would change over the next week. I was most (5)____ by a caring robot designed to help old people at home. It could (6)____ a glass of water, read the news aloud, and even tell simple jokes. A guide explained that such helpful machines must always (7)____ safe before they are sold to families. By the end of the visit, my view of robots had completely (8)____. I no longer saw them as something (9)____ and frightening. Instead, I felt excited about a future in which clever machines and people work (10)____.', 146, 2, '[{"q":"1","answer":"A","options":["fair","shop","garden","river"],"explanation":"a robot fair 机器人展会。"},{"q":"2","answer":"B","options":["sold","poured","lost","broke"],"explanation":"poured in 涌入。"},{"q":"3","answer":"C","options":["eat","buy","win","sleep"],"explanation":"win a chess game 赢得棋局。"},{"q":"4","answer":"D","options":["forget","waste","lose","predict"],"explanation":"predict the weather 预测天气。"},{"q":"5","answer":"A","options":["impressed","bored","angry","tired"],"explanation":"most impressed 印象最深。"},{"q":"6","answer":"B","options":["sell","fetch","break","hide"],"explanation":"fetch a glass of water 取来一杯水。"},{"q":"7","answer":"C","options":["look","feel","be proved","smell"],"explanation":"be proved safe 被证明安全(must + be done)。"},{"q":"8","answer":"D","options":["lost","stopped","failed","changed"],"explanation":"had changed 改变了。"},{"q":"9","answer":"A","options":["dangerous","lovely","cheap","tasty"],"explanation":"something dangerous 危险的东西。"},{"q":"10","answer":"B","options":["alone","together","apart","wrongly"],"explanation":"work together 一起工作。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U1', 'Writing My Own Sci-Fi Story', 'Our teacher asked each of us to write a short science (1)____ story for the class magazine. I decided to write about a girl who builds a time (2)____ in her bedroom. At first I found it hard to (3)____ what time travel would feel like. So I closed my eyes and tried to (4)____ the strange sights in my mind. In my story, the moment the girl pushed the (5)____, the walls of her room seemed to fall away. Days and nights passed (6)____ and faster, until she arrived in a far future city. There she met a friendly robot that could (7)____ her language. Writing the story (8)____ me hours, but I enjoyed every minute. My classmates said the ending was (9)____, because no one could guess it. Now I understand why so many people love science fiction: it lets your imagination travel (10)____ any limit.', 148, 2, '[{"q":"1","answer":"C","options":["price","noise","fiction","garden"],"explanation":"science fiction story 科幻故事。"},{"q":"2","answer":"D","options":["shop","market","river","machine"],"explanation":"a time machine 时间机器。"},{"q":"3","answer":"A","options":["imagine","sell","lose","break"],"explanation":"imagine what it would feel like 想象那感觉。"},{"q":"4","answer":"B","options":["forget","picture","waste","throw"],"explanation":"picture the sights 在脑中描绘景象。"},{"q":"5","answer":"C","options":["price","song","lever","meal"],"explanation":"pushed the lever 推动操纵杆。"},{"q":"6","answer":"D","options":["slower","quieter","softer","faster"],"explanation":"passed faster and faster 越来越快。"},{"q":"7","answer":"A","options":["speak","sell","lose","break"],"explanation":"speak her language 会说她的语言。"},{"q":"8","answer":"B","options":["sold","took","lost","broke"],"explanation":"took me hours 花了我几个小时。"},{"q":"9","answer":"C","options":["boring","useless","surprising","ugly"],"explanation":"the ending was surprising 结局出人意料。"},{"q":"10","answer":"D","options":["inside","below","near","beyond"],"explanation":"travel beyond any limit 超越一切界限。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U1', 'The Smart Kitchen', 'My uncle has turned his kitchen into a fully smart (1)____. As soon as he walks in, the lights come on by (2)____. A small cooking robot can (3)____ exactly how much flour and sugar a cake needs. It will then (4)____ the ingredients together without any help. If something starts to burn, an alarm is (5)____ at once, and the heat is turned down. My uncle says the robot must (6)____ be cleaned after each meal, just like ordinary tools. The best part is that boring kitchen (7)____ is now done by the machine, so my uncle has more time to relax. Of course, he still (8)____ to cook special dishes himself, because he enjoys it. He believes that good technology should help people, not (9)____ them. Thanks to his smart kitchen, family dinners have become easier and far more (10)____.', 142, 2, '[{"q":"1","answer":"A","options":["room","river","garden","street"],"explanation":"a smart room 智能房间(厨房)。"},{"q":"2","answer":"B","options":["mistake","itself","noise","price"],"explanation":"by itself 自动地(灯自己亮)。"},{"q":"3","answer":"C","options":["forget","waste","measure","lose"],"explanation":"measure how much 量取多少。"},{"q":"4","answer":"D","options":["sell","lose","break","mix"],"explanation":"mix the ingredients 把原料混合。"},{"q":"5","answer":"A","options":["sounded","eaten","sold","drawn"],"explanation":"an alarm is sounded 警报响起。"},{"q":"6","answer":"B","options":["never","regularly","hardly","rarely"],"explanation":"must regularly be cleaned 须定期清洁。"},{"q":"7","answer":"C","options":["song","price","work","noise"],"explanation":"kitchen work 厨房杂活。"},{"q":"8","answer":"D","options":["refuses","fails","forgets","likes"],"explanation":"still likes to cook 仍喜欢亲手做。"},{"q":"9","answer":"A","options":["replace","help","thank","please"],"explanation":"not replace them 而非取代他们。"},{"q":"10","answer":"B","options":["boring","enjoyable","useless","dangerous"],"explanation":"more enjoyable 更愉快。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U1', 'Dreaming of Space', 'Ever since I was a child, I have (1)____ of travelling to a distant planet. In my favourite science fiction books, brave people (2)____ huge spaceships across the stars to build new homes. They face many (3)____, such as strange weather and unknown dangers. Yet they never give (4)____, because their dream is too important. Sometimes their ships are (5)____ by storms of dust, but the crew always finds a way to repair them. On these far worlds, intelligent robots often (6)____ the heaviest work, so that humans can stay safe. I know that such journeys may not (7)____ in my lifetime. Still, real scientists are already (8)____ ways to live on the Moon and Mars. Reading these stories makes me want to study hard and join them one day. They remind me that today''s (9)____ dream can become tomorrow''s (10)____ truth.', 142, 2, '[{"q":"1","answer":"C","options":["sold","lost","dreamed","broke"],"explanation":"dreamed of 梦想着。"},{"q":"2","answer":"D","options":["eat","buy","sleep","fly"],"explanation":"fly spaceships 驾驶飞船。"},{"q":"3","answer":"A","options":["difficulties","prices","songs","noises"],"explanation":"many difficulties 许多困难。"},{"q":"4","answer":"B","options":["in","up","off","out"],"explanation":"give up 放弃。"},{"q":"5","answer":"C","options":["sold","fed","hit","paid"],"explanation":"are hit by storms 被风暴袭击(被动)。"},{"q":"6","answer":"D","options":["forget","waste","lose","do"],"explanation":"do the heaviest work 干最重的活。"},{"q":"7","answer":"A","options":["happen","sell","break","lose"],"explanation":"may not happen 也许不会发生(happen 不及物)。"},{"q":"8","answer":"B","options":["selling","exploring","losing","breaking"],"explanation":"exploring ways 探索方法。"},{"q":"9","answer":"C","options":["cheap","tasty","wild","loud"],"explanation":"a wild dream 大胆的梦想。"},{"q":"10","answer":"D","options":["false","empty","quiet","real"],"explanation":"real truth 真实的现实。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·对话 Choosing a Sci-Fi Film', '选择性必修四 U1 · dialogue', 3, 'Mia: There''s a science fiction film festival this weekend. Want to go, Sam?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·短文 What Is Science Fiction', '选择性必修四 U1 · passage', 2, 'Science fiction is a kind of story about the future and about science.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·对话 An Interview with a Sci-Fi Expert', '选择性必修四 U1 · dialogue', 3, 'Host: Welcome. You are an expert in science fiction. Do you have robots at home?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·短文 The Three Laws of Robotics', '选择性必修四 U1 · passage', 2, 'The famous writer Isaac Asimov created three laws to keep robots safe.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·对话 Talking about an AI Helper', '选择性必修四 U1 · dialogue', 3, 'Lucy: My grandfather just got a small AI helper. It''s amazing!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U1 听力·短文 Tips for Writing a Sci-Fi Story', '选择性必修四 U1 · passage', 2, 'Here are some simple tips for writing your own science fiction story.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (12, 'Write a Sci-Fi Story about a Robot You Invent(写一篇关于你发明的机器人的科幻短篇)', 'My Robot Friend', '假设你是李华,学校科幻社团征集''我发明的机器人''短篇故事。请用英语写一篇约100词的科幻短篇,内容包括:① 介绍你发明的机器人或AI装置(名字、样子、能做什么);② 讲一件它帮助了人的小事;③ 结尾点出你对人与机器人未来相处的看法。注意:适当使用被动语态(如 The robot was built… / It can be controlled…),情节连贯、想象合理。', 'Suppose you are Li Hua. Your school sci-fi club is collecting short stories called ''A Robot I Invented''. Write a sci-fi short story (about 100 words) including: 1) an introduction to the robot or AI device you invent (its name, looks and abilities); 2) a small event in which it helps someone; 3) an ending that shows your view of how humans and robots may live together in the future. Use the passive voice where it fits naturally.', '["介绍机器人(name / looks / what it can do)","讲一件帮助人的小事(a small helpful event)","结尾点出人机未来观点(your view of the future)","适当使用被动语态、情节连贯、想象合理"]'::jsonb, 70, 100, 'Last winter I invented a small robot and named it Leo. Leo is round and silver, with two soft hands and a friendly voice. It can fetch things, read the news aloud and even calculate how long my homework will take. One snowy morning, my grandmother slipped near the door. Before I could move, Leo had already reached her and helped her up. Later it was praised by my whole family. Of course, Leo must be tested carefully so that it is always safe. I believe that robots like Leo should be welcomed as gentle helpers. If clear rules are followed, humans and machines can surely live happily together.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Last winter I invented a small robot and named it Leo.","Before I could move, Leo had already reached her and helped her up.","Leo must be tested carefully so that it is always safe.","If clear rules are followed, humans and machines can surely live happily together."]'::jsonb, '[{"wrong":"The robot was build last year.","correct":"The robot was built last year.","note":"被动语态用过去分词 built,不是原形 build。"},{"wrong":"It can fetched things for us.","correct":"It can fetch things for us.","note":"情态动词 can 后接动词原形 fetch。"},{"wrong":"The robot must tested before use.","correct":"The robot must be tested before use.","note":"情态动词的被动:must + be + done。"}]'::jsonb, '【科幻短篇结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (12, 'elective4', 'U1', '{"title":"被动语态复习·各时态/情态被动 速查","intro":"当主语是动作的承受者时,用被动语态:be + 过去分词(done)。be 的形式随时态变化;情态动词后用 be done;不及物动词没有被动。判断口诀:主语''被''怎么样→用被动;时态看语境;情态后 be done。","table":{"headers":["时态 / 类型","被动结构 / 例句"],"rows":[["一般现在","am/is/are done:The work is done by robots."],["一般过去","was/were done:The robot was built last year."],["一般将来","will be done:A venue will be built next month."],["现在完成","has/have been done:It has been tested many times."],["过去完成","had been done:The house had been transformed before the party."],["现在进行","is/are being done:A new robot is being built now."],["过去进行","was/were being done:The surface was being changed."],["情态被动","can/must/should/may + be done:The robot must be repaired."]]},"specialRules":[{"rule":"情态动词后接 be done(不是 be doing / be do)","mark":"must be repaired √ / must repaired ×"},{"rule":"不及物动词没有被动(happen/appear/disappear/rise/fall/exist)","mark":"What happened? √ / What was happened? ×"},{"rule":"施动者用 by 引出,无关紧要时可省略","mark":"written by Liu Cixin"},{"rule":"口语常用 get done 表被动,强调结果/意外","mark":"The machine got flipped on its side."}],"why":["被动语态把动作的''承受者''放到主语位置,用来强调动作的对象、或当施动者未知、不重要时;be 始终随时态和数变化,真正表达''被''的是过去分词 done。"],"gaokaoPoints":["语法填空高频:用括号动词的''正确被动形式''填空,先判断主语是否承受动作,再由语境定时态。","情态动词的被动(must/should/can + be done)与不及物动词不能用被动(happen/appear)是常见陷阱。"],"examVsReal":[{"exam":"The novel was written by Liu Cixin.(考试/书面)","real":"Liu Cixin wrote the novel.","note":"考试爱考被动+by;真实表达若施动者重要,主动更直接有力。"},{"exam":"The window was broken.(考试)","real":"The window got broken.","note":"考试多用 be done;口语里 get done 更常见,强调意外结果。"}]}'::jsonb);
